def func_to_sig(f):
    """Called from jsproxy_call.c when we're about to call a callable.

    Has to return an appropriate JsFuncSignature.
    """
    cache_name = "_js_sig"
    if getattr(f, "__qualname__", None) == "type":
        cls = f.__args__[0]
        cache = cls
    else:
        if isclass(f):
